const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Adirondack Mountains region
  const adirondacks = ee.Geometry.Polygon([
    [[-74.8, 43.2], [-73.3, 43.2], [-73.3, 44.3], [-74.8, 44.3], [-74.8, 43.2]]
  ]);

  // 2. Define dates
  const date1 = '2022-10-01';
  const date2 = '2022-10-08';

  // 3. Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const scl = image.select('SCL');
    const mask = scl.neq(3).and(scl.neq(8)).and(scl.neq(9)).and(scl.neq(10));
    return image.updateMask(mask);
  }

  // 4. Function to calculate brown/orange index (senescence)
  // Brown/orange = high Red, moderate Green, lower NIR relative to summer
  function calculateBrownness(image) {
    const red = image.select('B4');
    const nir = image.select('B8');
    const swir = image.select('B11');
    // Senescence index: (Red + SWIR) / (NIR + 0.1) - higher values = more brown/orange
    const brownIndex = red.add(swir).divide(nir.add(0.1));
    return brownIndex.rename('brown_index');
  }

  // 5. Get Sentinel-2 data for Oct 1
  let col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(adirondacks)
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const size1 = col1.size().getInfo();
  console.log(`Oct 1 Images: ${size1}`);

  if (size1 === 0) {
    console.log('No Sentinel-2 data for Oct 1, trying Landsat 9');
    col1 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(adirondacks)
      .filterDate(date1, ee.Date(date1).advance(1, 'day'));
    if (col1.size().getInfo() === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 6. Get Sentinel-2 data for Oct 8
  let col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(adirondacks)
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const size2 = col2.size().getInfo();
  console.log(`Oct 8 Images: ${size2}`);

  if (size2 === 0) {
    console.log('No Sentinel-2 data for Oct 8, trying Landsat 9');
    col2 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(adirondacks)
      .filterDate(date2, ee.Date(date2).advance(1, 'day'));
    if (col2.size().getInfo() === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 7. Process images
  const img1 = maskS2clouds(col1.median());
  const img2 = maskS2clouds(col2.median());

  const brown1 = calculateBrownness(img1);
  const brown2 = calculateBrownness(img2);

  // 8. Calculate statistics
  const stats1 = brown1.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: adirondacks,
    scale: 3000,
    maxPixels: 1e9
  });

  const stats2 = brown2.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: adirondacks,
    scale: 3000,
    maxPixels: 1e9
  });

  const mean1 = stats1.get('brown_index_mean').getInfo();
  const count1 = stats1.get('brown_index_count').getInfo();
  const mean2 = stats2.get('brown_index_mean').getInfo();
  const count2 = stats2.get('brown_index_count').getInfo();

  console.log(`Oct 1 - Brownness: ${mean1}, Valid Pixels: ${count1}`);
  console.log(`Oct 8 - Brownness: ${mean2}, Valid Pixels: ${count2}`);

  // 9. Validation
  if (count1 === 0 || count2 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  if (mean1 === null || mean2 === null || isNaN(mean1) || isNaN(mean2)) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 10. Final comparison
  if (mean2 > mean1) {
    console.log('More brown/orange on Oct 8 than Oct 1');
    console.log('<answer>A</answer>');
  } else {
    console.log('Not more brown/orange on Oct 8 than Oct 1');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
